// Node.js' HTTP/2 implementation queues a chunk passed to `write()` as a single
// unit on the session. When the client cancels the stream while a multi-megabyte
// chunk is still queued, the session is left holding data it can no longer flush
// and the following streams on that connection stall. Writing in bounded chunks
// keeps the outgoing queue drainable.
const HTTP2_MAX_WRITE_CHUNK = 65536

function writePayload (res, payload) {
  // `stream` is only defined on an Http2ServerResponse, HTTP/1 is unaffected
  if (res.stream === undefined || Buffer.byteLength(payload) <= HTTP2_MAX_WRITE_CHUNK) {
    res.write(payload)
    return
  }

  const buffer = Buffer.isBuffer(payload) ? payload : Buffer.from(payload)
  for (let offset = 0; offset < buffer.length; offset += HTTP2_MAX_WRITE_CHUNK) {
    // the peer may have cancelled the stream while we were writing
    if (res.destroyed || res.writableEnded) return
    res.write(buffer.subarray(offset, offset + HTTP2_MAX_WRITE_CHUNK))
  }
}
